"use client";

import { type KeyboardEvent, useId, useState } from "react";

import { CheckIcon, ChevronDownIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { cn } from "@/lib/utils";

import { formatWhole } from "../lib/format";
import { STATUS_SURFACE, STATUS_TEXT } from "../lib/status";
import { BlockFrame } from "../parts/block-frame";
import { RollingText } from "../parts/rolling-text";
import { ScaleIcon } from "./icons";
import { DRAFT_ID, TEST_CASES, VERSIONS, countTokens, sampleReply, variablesIn } from "./prompt-studio/data";
import { PromptEditor } from "./prompt-studio/prompt-editor";
import { TestPanel } from "./prompt-studio/test-panel";
import { VersionDiff } from "./prompt-studio/version-diff";
import { VersionList } from "./prompt-studio/version-list";
import { words } from "./shared/answer";
import { MODELS, modelById } from "./shared/models";
import { useWordStream } from "./shared/use-word-stream";

type Part = "system" | "user";

/**
 * Edits, tests and ships one prompt template. Variables show as chips, a
 * test run streams a reply from the chosen model, and promoting a version
 * moves the production marker, with undo. Ctrl or Cmd with Enter runs the
 * selected test from anywhere in the card.
 */
export function PromptStudio({ className }: { className?: string }) {
  const titleId = useId();
  const [versions, setVersions] = useState(VERSIONS);
  const [selectedId, setSelectedId] = useState(DRAFT_ID);
  const [productionId, setProductionId] = useState("v3");
  const [previousId, setPreviousId] = useState<string | null>(null);
  const [announce, setAnnounce] = useState("");
  const [part, setPart] = useState<Part>("user");
  const [compare, setCompare] = useState(false);
  const [modelId, setModelId] = useState(MODELS[1]!.id);
  const [caseId, setCaseId] = useState(TEST_CASES[0]!.id);
  const [values, setValues] = useState(() => Object.fromEntries(TEST_CASES.map((item) => [item.id, { ...item.values }])));
  const [reply, setReply] = useState("");
  const stream = useWordStream({ delay: 400, interval: 60 });

  const version = versions.find((item) => item.id === selectedId) ?? versions[0]!;
  const production = versions.find((item) => item.id === productionId) ?? versions[0]!;
  const model = modelById(modelId);
  const caseValues = values[caseId] ?? {};
  const used = variablesIn(`${version.system} ${version.user}`);
  const tokens = countTokens(version.system) + countTokens(version.user);
  const isDraft = version.id === DRAFT_ID;
  const state = version.id === productionId ? "Production" : isDraft ? "Draft" : "Saved";

  const edit = (value: string) =>
    setVersions((list) => list.map((item) => (item.id === version.id ? { ...item, [part]: value } : item)));

  const run = () => {
    const text = sampleReply(version.user, caseValues, model.name);
    setReply(text);
    stream.start(words(text).length);
  };

  const promote = () => {
    setPreviousId(productionId);
    setProductionId(version.id);
    setAnnounce(`${version.label} is now in production.`);
  };

  const undo = () => {
    if (!previousId) return;
    const back = versions.find((item) => item.id === previousId);
    setProductionId(previousId);
    setPreviousId(null);
    setAnnounce(`${back?.label ?? "The earlier version"} is back in production.`);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
      event.preventDefault();
      run();
    }
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className} onKeyDown={onKeyDown}>
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4">
        <div className="flex min-w-0 flex-wrap items-center gap-2">
          <h2 id={titleId} className="text-base font-semibold">
            Visit reminder
          </h2>
          <span className="rounded-md bg-muted px-1.5 py-0.5 font-mono text-xs text-muted-foreground">{version.label}</span>
          <span
            className={cn(
              "rounded-full px-2 py-0.5 text-xs font-medium",
              state === "Production" ? [STATUS_SURFACE.good, STATUS_TEXT.good] : state === "Draft" ? [STATUS_SURFACE.watch, STATUS_TEXT.watch] : "bg-muted text-muted-foreground",
            )}
          >
            {state}
          </span>
        </div>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="sm" aria-label={`Model: ${model.name}`}>
              <span aria-hidden="true" className={cn("size-2 rounded-full", model.hue)} />
              {model.name}
              <ChevronDownIcon aria-hidden="true" className="size-4 text-muted-foreground" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-60">
            <DropdownMenuLabel>Model for test runs</DropdownMenuLabel>
            <DropdownMenuRadioGroup value={modelId} onValueChange={setModelId}>
              {MODELS.map((item) => (
                <DropdownMenuRadioItem key={item.id} value={item.id}>
                  <span className="flex flex-col">
                    <span>{item.name}</span>
                    <span className="text-xs text-muted-foreground">{item.provider}</span>
                  </span>
                </DropdownMenuRadioItem>
              ))}
            </DropdownMenuRadioGroup>
          </DropdownMenuContent>
        </DropdownMenu>
      </header>

      <div className="grid @3xl:grid-cols-[1fr_18rem]">
        <div className="flex min-w-0 flex-col gap-5 p-5">
          <Tabs value={part} onValueChange={(value) => setPart(value === "system" ? "system" : "user")}>
            <div className="flex flex-wrap items-center justify-between gap-2">
              <TabsList aria-label="Prompt part">
                <TabsTrigger value="system">System</TabsTrigger>
                <TabsTrigger value="user">User</TabsTrigger>
              </TabsList>
              <div className="flex items-center gap-3">
                <span className="text-xs text-muted-foreground">
                  <RollingText text={formatWhole(tokens)} /> tokens
                </span>
                <Button
                  size="sm"
                  variant={compare ? "secondary" : "ghost"}
                  aria-pressed={compare}
                  disabled={version.id === productionId}
                  onClick={() => setCompare(!compare)}
                >
                  <ScaleIcon aria-hidden="true" className="size-4" />
                  Compare with production
                </Button>
              </div>
            </div>
            {(["system", "user"] as const).map((key) => (
              <TabsContent key={key} value={key}>
                <div className="flex flex-col gap-3 pt-2">
                <PromptEditor label={`${key === "system" ? "System" : "User"} prompt, ${version.label}`} value={version[key]} onChange={edit} readOnly={!isDraft} />
                {!isDraft ? (
                  <p className="text-xs text-muted-foreground">Saved versions are read-only. Select {DRAFT_ID} to edit the draft.</p>
                ) : (
                  <p className="text-xs text-muted-foreground">Type two braces to insert a variable.</p>
                )}
                {compare && version.id !== productionId ? (
                  <VersionDiff before={production[key]} after={version[key]} beforeLabel={production.label} afterLabel={version.label} />
                ) : null}
                </div>
              </TabsContent>
            ))}
          </Tabs>

          <TestPanel
            caseId={caseId}
            values={caseValues}
            used={used}
            modelName={model.name}
            reply={reply}
            shown={stream.shown}
            status={stream.status}
            onCase={setCaseId}
            onValue={(name, value) => setValues((all) => ({ ...all, [caseId]: { ...all[caseId], [name]: value } }))}
            onRun={run}
            onStop={stream.stop}
          />
        </div>

        <aside className="flex flex-col gap-3 border-t border-border p-5 @3xl:border-t-0 @3xl:border-l" aria-label="Versions">
          <VersionList
            versions={versions}
            selectedId={selectedId}
            productionId={productionId}
            previousId={previousId}
            onSelect={setSelectedId}
            onPromote={promote}
            onUndo={undo}
          />
          <p role="status" className="flex items-center gap-1.5 text-xs text-muted-foreground">
            {announce ? <CheckIcon aria-hidden="true" className="size-3.5 text-chart-3" /> : null}
            {announce}
          </p>
        </aside>
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

