/** A variable the prompt can use, written as {{name}} in the text. */
export interface PromptVariable {
  name: string;
  /** What the variable holds, shown in the insert list. */
  hint: string;
}

/** One saved or draft version of the reminder prompt. */
export interface PromptVersion {
  id: string;
  label: string;
  /** A short line on what changed. */
  note: string;
  date: string;
  system: string;
  user: string;
}

/** One saved set of sample values to test the prompt with. */
export interface TestCase {
  id: string;
  name: string;
  values: Record<string, string>;
}

/** The variables Fernhill knows about. */
export const VARIABLES: PromptVariable[] = [
  { name: "patient_name", hint: "The patient's full name" },
  { name: "practitioner", hint: "Who the patient sees" },
  { name: "clinic", hint: "The clinic name" },
  { name: "visit_time", hint: "Day and time of the visit" },
  { name: "room", hint: "The room or suite" },
];

