/** Every {{name}} the text uses, in order of first use. */
export function variablesIn(text: string): string[] {
  const found = [...text.matchAll(/\{\{(\w+)\}\}/g)].map((match) => match[1]!);
  return [...new Set(found)];
}

/** A rough token count: about four characters to a token. */
export const countTokens = (text: string) => Math.ceil(text.trim().length / 4);

/** The reminder a model writes for these values. It uses only the variables the prompt asks for. */
export function sampleReply(user: string, values: Record<string, string>, model: string): string {
  const used = new Set(variablesIn(user));
  const value = (name: string, fallback: string) => (used.has(name) ? values[name] || fallback : fallback);
  const first = value("patient_name", "there").split(" ")[0];
  const who = used.has("practitioner") ? ` with ${value("practitioner", "")}` : "";
  const where = used.has("clinic") ? ` at ${value("clinic", "")}` : "";
  const room = used.has("room") ? `, in ${value("room", "")}` : "";
  const when = value("visit_time", "soon");
  const move = user.includes("move the booking")
    ? " If you need to move it, reply to this message or use the link in your booking email."
    : "";
  const opener = model.startsWith("Larch") ? `Hello ${first},` : `Hi ${first},`;
  return `${opener} a quick reminder of your visit${who}${where} on ${when}${room}. Please arrive ten minutes early.${move} See you soon, the Fernhill team.`;
}

