import { type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

import { VARIABLES } from "./data";

/** Props for the prompt text field. */
export interface PromptEditorProps {
  label: string;
  value: string;
  onChange: (value: string) => void;
  readOnly: boolean;
}

const TRIGGER = /\{\{(\w*)$/;

/** The text with each {{name}} drawn as a tinted chip. The chip adds no width, so it lines up with the field above it. */
function Highlight({ text }: { text: string }) {
  return (
    <>
      {text.split(/(\{\{\w+\}\})/).map((piece, index) =>
        /^\{\{\w+\}\}$/.test(piece) ? (
          <span key={index} className="rounded-sm bg-chart-2/20 text-chart-2 box-decoration-clone">
            {piece}
          </span>
        ) : (
          <span key={index}>{piece}</span>
        ),
      )}
      {/* A trailing space keeps the last empty line as tall as the field's. */}{" "}
    </>
  );
}

/**
 * A prompt field that shows variables as chips. Typing two braces opens the
 * list of known variables: arrows move, Enter or Tab inserts, Escape closes.
 */
export function PromptEditor({ label, value, onChange, readOnly }: PromptEditorProps) {
  const field = useRef<HTMLTextAreaElement>(null);
  const listId = useId();
  const [query, setQuery] = useState<string | null>(null);
  const [active, setActive] = useState(0);
  // Where the caret goes once an inserted chip has rendered.
  const pendingCaret = useRef<number | null>(null);

  useEffect(() => {
    const box = field.current;
    const caret = pendingCaret.current;
    if (!box || caret === null) return;
    pendingCaret.current = null;
    box.focus();
    box.setSelectionRange(caret, caret);
  }, [value]);

  const options = query === null ? [] : VARIABLES.filter((item) => item.name.startsWith(query.toLowerCase()));
  const open = options.length > 0;

  const readTrigger = (text: string, caret: number) => {
    const match = TRIGGER.exec(text.slice(0, caret));
    setQuery(match ? match[1]! : null);
    setActive(0);
  };

  const insert = (name: string) => {
    const box = field.current;
    if (!box) return;
    const caret = box.selectionStart;
    const before = value.slice(0, caret).replace(TRIGGER, `{{${name}}}`);
    const after = value.slice(caret).replace(/^\w*\}{0,2}/, "");
    onChange(before + after);
    setQuery(null);
    pendingCaret.current = before.length;
  };

  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    if (!open) return;
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      const step = event.key === "ArrowDown" ? 1 : -1;
      setActive((current) => (current + step + options.length) % options.length);
    } else if ((event.key === "Enter" && !event.metaKey && !event.ctrlKey) || event.key === "Tab") {
      event.preventDefault();
      insert(options[active]!.name);
    } else if (event.key === "Escape") {
      event.preventDefault();
      setQuery(null);
    }
  };

  return (
    <div className="relative">
      {/* The highlighted copy sits under the field, which shows its caret and
          selection but not its text. The field inherits the mono font and the
          transparent text from the inner wrapper, which also clears the
          field's fill so the copy shows through; the outer wrapper paints that
          fill instead. The copy matches the field's border, padding and type
          size, so every character lines up. */}
      <div className="rounded-md bg-background">
        <div className="grid font-mono text-transparent caret-foreground [--background:transparent]">
          <div
            aria-hidden="true"
            className="pointer-events-none col-start-1 row-start-1 border border-transparent px-3 py-2 text-base break-words whitespace-pre-wrap text-foreground md:text-sm"
          >
            <Highlight text={value} />
          </div>
          <Textarea
            ref={field}
            aria-label={label}
            role="combobox"
            aria-expanded={open}
            aria-controls={listId}
            aria-autocomplete="list"
            aria-activedescendant={open ? `${listId}-${active}` : undefined}
            aria-readonly={readOnly}
            readOnly={readOnly}
            spellCheck={false}
            value={value}
            onChange={(event) => {
              onChange(event.target.value);
              readTrigger(event.target.value, event.target.selectionStart);
            }}
            onKeyDown={onKeyDown}
            onBlur={() => setQuery(null)}
            className={cn(
              "col-start-1 row-start-1 min-h-28 resize-none overflow-hidden",
              readOnly && "cursor-default",
            )}
          />
        </div>
      </div>
      <ul
        id={listId}
        role="listbox"
        aria-label="Variables"
        hidden={!open}
        className="absolute inset-x-0 top-full z-20 mt-1 max-w-xs rounded-lg border border-border bg-popover p-1 text-popover-foreground shadow-md"
      >
        {options.map((item, index) => (
          <li
            key={item.name}
            id={`${listId}-${index}`}
            role="option"
            aria-selected={index === active}
            onPointerDown={(event) => {
              event.preventDefault();
              insert(item.name);
            }}
            onPointerMove={() => setActive(index)}
            className={cn(
              "flex cursor-pointer flex-col rounded-md px-2 py-1.5 text-sm",
              index === active && "bg-accent text-accent-foreground",
            )}
          >
            <span className="font-mono text-chart-2">{`{{${item.name}}}`}</span>
            <span className="text-xs text-muted-foreground">{item.hint}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

