// Each row is 3.5rem tall with no gap, so the marker moves in whole rows.
const ROW = 3.5;

/**
 * The versions, newest first, with a production marker. Promoting a version
 * glides the marker to its row with an ease that never overshoots, and undo
 * glides it back.
 */
export function VersionList({ versions, selectedId, productionId, previousId, onSelect, onPromote, onUndo }: VersionListProps) {
  const rows = [...versions].reverse();
  const markerRow = rows.findIndex((version) => version.id === productionId);
  const selected = versions.find((version) => version.id === selectedId);
  const canPromote = selectedId !== productionId;

  const markerStyle: VarStyle = { "--y": `${markerRow * ROW}rem` };
  return (
    <div className="flex flex-col gap-3">
      <h3 className="text-sm font-medium">Versions</h3>
      <div className="relative">
        <span
          aria-hidden="true"
          style={markerStyle}
          className="pointer-events-none absolute top-0 right-2 flex h-14 translate-y-(--y) items-center motion-safe:transition-transform motion-safe:duration-500 motion-safe:ease-out"
        >
          <span className={cn("rounded-full px-2 py-0.5 text-xs font-medium", STATUS_SURFACE.good, STATUS_TEXT.good)}>
            Production
          </span>
        </span>
        <ul className="flex flex-col">
          {rows.map((version) => {
            const isSelected = version.id === selectedId;
            return (
              <li key={version.id} className="h-14">
                <Button
                  variant={isSelected ? "secondary" : "ghost"}
                  aria-pressed={isSelected}
                  onClick={() => onSelect(version.id)}
                  className={cn("h-full w-full justify-start    text-left ")}
                >
                  <span
                    className={cn(
                      "flex size-8 shrink-0 items-center justify-center rounded-md font-mono text-xs font-semibold",
                      isSelected ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground",
                    )}
                  >
                    {version.label}
                  </span>
                  <span className="flex min-w-0 flex-col pr-24">
                    <span className="truncate text-sm">{version.note}</span>
                    <span className="text-xs text-muted-foreground">
                      {version.id === DRAFT_ID ? "Draft, edited today" : `Saved ${version.date}`}
                      {version.id === productionId ? <span className="sr-only">, in production</span> : null}
                    </span>
                  </span>
                </Button>
              </li>
            );
          })}
        </ul>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <Button size="sm" disabled={!canPromote} onClick={onPromote}>
          <CheckIcon aria-hidden="true" className="size-4" />
          {canPromote ? `Promote ${selected?.label ?? ""}` : "In production"}
        </Button>
        {previousId ? (
          <Button size="sm" variant="outline" onClick={onUndo}>
            <UndoIcon aria-hidden="true" className="size-4" />
            Undo
          </Button>
        ) : null}
      </div>
    </div>
  );
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };

/** How hard a model thinks before it answers. */
